'use strict';

const franc = require('franc-min');

const mainRequire = (...args) => (process.mainModule || require.main).require(...args);
const meta = mainRequire('./src/meta');

const plugin = module.exports;

const SETTINGS_HASH = 'language-filter';
const DEFAULT_ALLOWED_LANGS = ['eng'];
const DEFAULT_MIN_LENGTH = 10;
const LANGUAGE_LABELS = {
	eng: 'English',
	gle: 'Irish (Gaeilge)',
	fra: 'French',
	deu: 'German',
	spa: 'Spanish',
	ita: 'Italian',
	por: 'Portuguese',
	nld: 'Dutch',
	pol: 'Polish',
	swe: 'Swedish',
	nor: 'Norwegian',
	dan: 'Danish',
	fin: 'Finnish',
	rus: 'Russian',
	ukr: 'Ukrainian',
	ara: 'Arabic',
	zho: 'Chinese',
	jpn: 'Japanese',
	kor: 'Korean',
	hin: 'Hindi',
	tur: 'Turkish',
	vie: 'Vietnamese',
	ind: 'Indonesian',
	ces: 'Czech',
	ron: 'Romanian',
	hun: 'Hungarian',
	ell: 'Greek',
	heb: 'Hebrew',
	cat: 'Catalan',
	slk: 'Slovak',
};

let settingsCache;

plugin.init = async function ({ router }) {
	const routeHelpers = mainRequire('./src/routes/helpers');
	routeHelpers.setupAdminPageRoute(router, '/admin/plugins/language-filter', [], renderAdminPage);
	router.post('/admin/plugins/language-filter/save', saveSettings);
};

plugin.addAdminNavigation = async function (header) {
	header.plugins.push({
		route: '/plugins/language-filter',
		icon: 'fa-language',
		name: 'Language Filter',
	});
	return header;
};

plugin.filterTopicPost = async function (data = {}) {
	const text = firstText(data.content, data.title);
	await checkLanguage(text, data);
	return data;
};

plugin.filterTopicReply = async function (data = {}) {
	await checkLanguage(data.content, data);
	return data;
};

async function renderAdminPage(req, res) {
	const settings = await getSettings();
	res.render('admin/plugins/language-filter', {
		title: 'Language Filter',
		allowedLangs: settings.allowedLangs.join(','),
		minLength: settings.minLength,
		moreInfoUrl: settings.moreInfoUrl,
		minPostLength: meta.config.minimumPostLength || 0,
	});
}

async function saveSettings(req, res) {
	const selected = parseAllowedLangs(req.body.allowedLangs);
	if (!selected.length) {
		return res.status(400).json({ error: 'At least one language must be selected.' });
	}

	const minLength = normalizeMinLength(req.body.minLength);
	const minPostLength = parseInt(meta.config.minimumPostLength, 10) || 0;
	if (minLength < minPostLength) {
		return res.status(400).json({ error: 'Minimum text length must be greater than or equal to the minimum post length.' });
	}

	await meta.settings.set(SETTINGS_HASH, {
		allowedLangs: JSON.stringify(selected),
		minLength: minLength,
		moreInfoUrl: typeof req.body.moreInfoUrl === 'string' ? req.body.moreInfoUrl.trim() : '',
	});
	settingsCache = null;

	return res.json({ success: true });
}

async function getSettings() {
	if (settingsCache) {
		return settingsCache;
	}

	let settings;
	try {
		settings = await meta.settings.get(SETTINGS_HASH);
	} catch (err) {
		settings = null;
	}

	settingsCache = {
		allowedLangs: normalizeAllowedLangs(settings && settings.allowedLangs),
		minLength: normalizeMinLength(settings && settings.minLength),
		moreInfoUrl: typeof (settings && settings.moreInfoUrl) === 'string' ? settings.moreInfoUrl : '',
	};

	return settingsCache;
}

async function checkLanguage(content, data) {
	const settings = await getSettings();
	const text = stripHtml(typeof content === 'string' ? content : '');

	if (text.length < settings.minLength) {
		return;
	}

	const detected = franc(text);
	if (!detected || detected === 'und' || settings.allowedLangs.includes(detected)) {
		return;
	}

	throw createBlockedError(settings, detected);
}

function createBlockedError(settings, detected) {
	const allowedText = settings.allowedLangs.map((code) => LANGUAGE_LABELS[code] || code).join(' and ');
	const forumTitle = meta.config.title || 'this forum';
	const infoLink = `<a href="${settings.moreInfoUrl || ''}">More info</a>`;
	const err = new Error(`Posts in ${allowedText} are allowed on ${forumTitle}. Detected language: ${LANGUAGE_LABELS[detected] || detected}. ${infoLink}`);
	err.status = 403;
	return err;
}

function normalizeAllowedLangs(value) {
	const langs = parseAllowedLangs(value);
	return langs.length ? langs : DEFAULT_ALLOWED_LANGS.slice();
}

function parseAllowedLangs(value) {
	let langs = [];

	if (Array.isArray(value)) {
		langs = value;
	} else if (typeof value === 'string' && value.trim()) {
		try {
			const parsed = JSON.parse(value);
			if (Array.isArray(parsed)) {
				langs = parsed;
			} else {
				langs = value.split(',');
			}
		} catch (err) {
			langs = [];
		}
	}

	return langs.map(lang => String(lang).trim()).filter(Boolean);
}

function normalizeMinLength(value) {
	const parsed = parseInt(value, 10);
	return Number.isFinite(parsed) ? parsed : DEFAULT_MIN_LENGTH;
}

function firstText(content, title) {
	if (typeof content === 'string' && content.length) {
		return content;
	}
	if (typeof title === 'string' && title.length) {
		return title;
	}
	return '';
}

function stripHtml(text) {
	return text.replace(/<[^>]*>/g, '').trim();
}
